class Poll:
    def __init__(self, question: str) -> None:
        self.question = question
        self.options = []  # list to maintain order of option addition
        self.votes = {}    # option -> vote count mapping
        self.total_votes = 0

    def add_option(self, option: str) -> None:
        if option not in self.votes:
            self.options.append(option)
            self.votes[option] = 0

    def vote(self, voter: str, option: str) -> None:
        if option not in self.votes:
            raise ValueError(f"Option '{option}' does not exist")
        self.votes[option] += 1
        self.total_votes += 1

    def winner(self) -> str | None:
        if self.total_votes < 3:
            return None

        if not self.votes:
            return None

        # Find the maximum vote count
        max_votes = max(self.votes.values())

        # Find all options with maximum votes
        candidates = [opt for opt in self.options if self.votes[opt] == max_votes]

        # Return the last added option among the tied candidates
        # Since we iterate through self.options (which maintains insertion order),
        # the last candidate in this list is the one added last
        return candidates[-1] if candidates else None
